CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text NOT NULL DEFAULT '');
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own profile" ON public.profiles FOR SELECT TO authenticated USING (auth.uid() = id);
CREATE POLICY "Update own profile" ON public.profiles FOR UPDATE TO authenticated USING (auth.uid() = id) WITH CHECK (auth.uid() = id);
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES (NEW.id, coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END; $$;
CREATE TRIGGER create_user_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'user', UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own role" ON public.user_roles FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE TABLE public.site_content (key text PRIMARY KEY, value jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.site_content TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.site_content TO authenticated;
GRANT ALL ON public.site_content TO service_role;
ALTER TABLE public.site_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public site content" ON public.site_content FOR SELECT TO anon,authenticated USING (true);
CREATE POLICY "Admin edits content" ON public.site_content FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, kind text NOT NULL DEFAULT 'combo' CHECK(kind IN ('combo','single')), description text NOT NULL DEFAULT '', image_url text NOT NULL DEFAULT '', price numeric(12,2), original_price numeric(12,2), features jsonb NOT NULL DEFAULT '[]'::jsonb, published boolean NOT NULL DEFAULT false, starts_at timestamptz, ends_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.offers TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.offers TO authenticated;
GRANT ALL ON public.offers TO service_role;
ALTER TABLE public.offers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Visible offers" ON public.offers FOR SELECT TO anon,authenticated USING (published AND (starts_at IS NULL OR starts_at<=now()) AND (ends_at IS NULL OR ends_at>now()));
CREATE POLICY "Admin manages all offers including drafts" ON public.offers FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.ai_service_state (id text PRIMARY KEY, blocked boolean NOT NULL DEFAULT false, reason text NOT NULL DEFAULT '', status integer NOT NULL DEFAULT 200);
GRANT ALL ON public.ai_service_state TO service_role;
ALTER TABLE public.ai_service_state ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.ai_request_limits (key text PRIMARY KEY, window_start timestamptz NOT NULL DEFAULT now(), requests integer NOT NULL DEFAULT 0);
GRANT ALL ON public.ai_request_limits TO service_role;
ALTER TABLE public.ai_request_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.take_ai_request(_key text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE count_now integer; BEGIN INSERT INTO public.ai_request_limits(key,requests) VALUES(_key,1) ON CONFLICT(key) DO UPDATE SET requests=CASE WHEN ai_request_limits.window_start<now()-interval '1 hour' THEN 1 ELSE ai_request_limits.requests+1 END,window_start=CASE WHEN ai_request_limits.window_start<now()-interval '1 hour' THEN now() ELSE ai_request_limits.window_start END RETURNING requests INTO count_now; RETURN count_now<=10; END; $$;
REVOKE ALL ON FUNCTION public.take_ai_request(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.take_ai_request(text) TO service_role;